WITH with_windows AS (SELECT id, method, amount, paid_at, SUM(amount) OVER w_grp AS cumulative_amount, SUM(amount) OVER w_running AS running_amount, ROUND(amount / SUM(amount) OVER (PARTITION BY method, order_id), 4) AS amount_share FROM payments WINDOW w_grp AS (ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running AS (PARTITION BY order_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL 7 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM with_windows), sessions_payments AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps), kept_keys AS (SELECT method, id FROM sessions_payments EXCEPT ALL SELECT method, id FROM payments WHERE paid_at >= '2024-05-20'), verified AS (SELECT s.* FROM sessions_payments s JOIN kept_keys k ON s.method = k.method AND s.id = k.id), scored AS (SELECT id, method, cumulative_amount, running_amount, amount_share, session_start_flag, burst_id, MIN(amount_share) OVER (PARTITION BY method) AS method_min_amount_share, DENSE_RANK() OVER w_ordered AS amount_share_dense_rank, PERCENT_RANK() OVER w_running AS cumulative_amount_percent_rank FROM verified WINDOW w_ordered AS (PARTITION BY method ORDER BY amount_share), w_running AS (PARTITION BY method ORDER BY cumulative_amount DESC)), enriched AS (SELECT *, ROUND(running_amount / SUM(running_amount) OVER (PARTITION BY method), 4) AS running_amount_share, ROUND(cumulative_amount / SUM(cumulative_amount) OVER (PARTITION BY method), 4) AS cumulative_amount_share, RANK() OVER (PARTITION BY method ORDER BY cumulative_amount_percent_rank DESC NULLS FIRST) AS cumulative_amount_percent_rank_rank FROM scored), base AS (SELECT id, method, cumulative_amount, amount_share, session_start_flag, burst_id, method_min_amount_share, cumulative_amount_percent_rank, cumulative_amount_share, COALESCE(cumulative_amount_percent_rank_rank, 0) AS cumulative_amount_percent_rank_rank_filled, COALESCE(method, 'UNKNOWN') AS resolved_method FROM enriched WHERE session_start_flag >= 0), metrics AS (SELECT cumulative_amount, amount_share, burst_id, method_min_amount_share, cumulative_amount_percent_rank, cumulative_amount_share, RANK() OVER (PARTITION BY method ORDER BY session_start_flag DESC NULLS FIRST) AS session_start_flag_rank, COUNT(session_start_flag) OVER (PARTITION BY method) AS method_count_session_start_flag FROM base) SELECT CASE WHEN method_count_session_start_flag >= 15 THEN 'PREMIUM' ELSE 'STANDARD' END AS method_count_session_start_flag_tier, burst_id, COUNT(*) AS row_count, APPROX_PERCENTILE(amount_share, 0.9) AS amount_share_p90, ROUND(AVG(method_count_session_start_flag), 2) AS avg_method_count_session_start_flag, ROUND(AVG(session_start_flag_rank), 2) AS avg_session_start_flag_rank, ROUND(AVG(burst_id), 2) AS avg_burst_id FROM metrics GROUP BY GROUPING SETS ((CASE WHEN method_count_session_start_flag >= 15 THEN 'PREMIUM' ELSE 'STANDARD' END, burst_id), (CASE WHEN method_count_session_start_flag >= 15 THEN 'PREMIUM' ELSE 'STANDARD' END)) ORDER BY avg_burst_id DESC;
